/**
 * The view registry (spike S22 Q5; sharing-shaping R9 §View tabs): one row
 * per kind of view tab — a tab whose body is a view over vault and session
 * state rather than a note. The pure half is `VIEW_KINDS` in `panes.ts`
 * (what the layout reader and `openView` know); this is the Svelte half:
 * each kind's title, icon, component and palette command.
 *
 * Everything that used to hard-code the one kind reads this instead — the
 * pane renders `VIEWS[tab.view].component`, the strip takes its title and
 * icon, and the palette rows are generated by `viewCommands`. Adding a view
 * is one entry in `VIEW_KINDS` and one row here. `inspector` and `log` are
 * registered; `shared` and the harness's `session` register the same way.
 */
import { RadioTower, ScanSearch, ScrollText, type LucideIcon } from '@lucide/svelte'
import { getLL, type TranslationFunctions } from '@ohhi/i18n'
import type { Clock } from '@ohhi/vault'
import type { InSyncSpan } from '@ohhi/workspace'
import { getContext, hasContext, setContext, type Component } from 'svelte'
import type { Command } from './commands.js'
import type { ShellSpec } from './layout-spec.js'
import { VIEW_KINDS, type Tab, type TabView } from './panes.js'
import { realClock } from './real-clock.js'
import type { Workspace } from './workspace.svelte.js'
import Inspector from './components/Inspector.svelte'
import LogView from './components/LogView.svelte'
import SharedView from './components/SharedView.svelte'

/** What every view component is handed. */
export interface ViewProps {
  workspace: Workspace
  /** The tab it is rendered in (its `viewArg`, when the kind takes one). */
  tab: Tab
}

/**
 * The shell's actions a view tab OR a readout may take — the ONE verb
 * surface below the composition root (duplication review #1): handed down
 * as a Svelte context rather than threaded through `EditorArea` → `PaneTree`
 * → `Pane` as props, because a view needs verbs the pane tree has no
 * business knowing about (open the share sheet, the Settings tab, another
 * view). Set once by `App.svelte`; read with `getViewShell()` during a
 * component's init. Absent (a unit test, a view mounted on its own) →
 * `null`, and the component offers no such verb. A unit test injects one
 * with `viewShellContext(shell)` as `render`'s `context`.
 *
 * Every getter is a function, so the view reads the live value.
 */
export interface ViewShell {
  /** The shell's injected clock (golden rule 5); `shellClock()` reads it. */
  clock: Clock
  /**
   * Open a note: App's `openPath` — `panes.open: 'replace'`, recents, the
   * navigator drawer closing. `background` is Mod+click (a tab, stay put).
   */
  openPath(path: string, opts?: { background?: boolean }): void
  /** Open another view tab. */
  openView(id: TabView, arg?: string): void
  /** *Create* for an unresolved link (the Note menu's Links). */
  createFromLink(target: string): void
  /**
   * Rename a note from its inline title (P3, `file-actions.renameNote`): the
   * new basename without the extension. Resolves the new path, or null when
   * it was refused (already flashed).
   */
  renameNote(path: string, newName: string): Promise<string | null>
  /** *Pin as …* (quiet-shell F3): one region into the layout file in use. */
  pin(regions: Partial<ShellSpec['regions']>): void
  /** Settings, on a tab. */
  openSettings(tab?: 'sync'): void
  /** The share sheet for a folder (a new share, or a shared folder's links). */
  shareFolder(path: string): void
  /** *Add a shared folder…*, landing in `dir` ('' = the vault root). */
  addSharedFolder(dir?: string): void
  /** *Link a device…* (the owner's dialog). */
  linkDevice(): void
  /** Reveal a folder in the navigator. */
  revealFolder(path: string): void
  /** The relay new shares are minted on, and the operator secret ('' = none). */
  relayUrl(): string
  secret(): string
  /** Bumped when a share or device dialog closes: re-read the token lists. */
  revision(): number
  /** Per room, its rollup's last green span — relay receipt, not durability (`shared.svelte.ts`). */
  inSyncByRoom(): Record<string, InSyncSpan>
}

const VIEW_SHELL = Symbol('view-shell')

/** Provide the shell's actions to every view tab below (App.svelte, at init). */
export function setViewShell(shell: ViewShell): void {
  setContext(VIEW_SHELL, shell)
}

/** The shell's actions, or null when no shell provided them. Call during component init. */
export function getViewShell(): ViewShell | null {
  return hasContext(VIEW_SHELL) ? getContext<ViewShell>(VIEW_SHELL) : null
}

/**
 * The clock a view or readout ages its relative times on: the shell's
 * injected one, or the real clock when mounted with no shell. Call during
 * component init (it reads the context). A test pins it through the shell.
 */
export function shellClock(): Clock {
  return getViewShell()?.clock ?? realClock
}

/** `render(Component, { props, context: viewShellContext(shell) })` — a test's shell. */
export function viewShellContext(shell: ViewShell): Map<symbol, ViewShell> {
  return new Map([[VIEW_SHELL, shell]])
}

/** What a view's `when` may ask about the shell. */
export interface ViewContext {
  /** Developer tools are on (Settings › Developer, or `?debug=1`). */
  devtools(): boolean
}

export interface ViewDef {
  id: TabView
  /** The tab's title; `LL` is `$LL` in a component, `getLL()` in a module. */
  title(LL: TranslationFunctions, arg?: string): string
  icon: LucideIcon
  component: Component<ViewProps>
  /** The palette row that opens it. Ids are stable — a user's rebind keys on them. */
  command: {
    id: string
    title(LL: TranslationFunctions): string
    group(LL: TranslationFunctions): string
    /** Default binding, if the view has one. */
    keys?: string
  }
  /** Listed (and runnable) only while this holds. */
  when?(ctx: ViewContext): boolean
  /**
   * The argument the palette row opens it with, for a kind that takes one
   * (e.g. the current session). Absent: the view is opened without one.
   */
  arg?(): string | undefined
}

export const VIEWS = {
  inspector: {
    id: 'inspector',
    // A path argument is one file's detail alone (devtools-shaping E3).
    title: (LL, arg) => (arg ? LL.web.devtools.tab_file({ path: arg }) : LL.web.devtools.tab()),
    icon: ScanSearch,
    component: Inspector,
    command: {
      id: 'app.inspector',
      title: (LL) => LL.web.commands.inspector(),
      group: (LL) => LL.web.commands.groups.developer(),
    },
    when: (ctx) => ctx.devtools(),
  },
  // quiet-shell F12: the session's events. For everyone — no `when`.
  log: {
    id: 'log',
    // `changes` is the Shared view's *Show all*: the same log, change kinds only.
    title: (LL, arg) => (arg === 'changes' ? LL.web.log.title_changes() : LL.web.log.title()),
    icon: ScrollText,
    component: LogView,
    command: {
      id: 'app.log',
      title: (LL) => LL.web.commands.log(),
      group: (LL) => LL.web.commands.groups.developer(),
    },
  },
  // sharing E2: the shared world as a place. For everyone; the pill is its door.
  shared: {
    id: 'shared',
    title: (LL) => LL.web.shared.title(),
    icon: RadioTower,
    component: SharedView,
    command: {
      id: 'app.shared',
      title: (LL) => LL.web.commands.shared(),
      group: (LL) => LL.web.commands.groups.share(),
      keys: 'Mod+Shift+S',
    },
  },
} satisfies Record<TabView, ViewDef>

/** The registry entry for a kind (every `TabView` has one, by type). */
export function viewDef(id: TabView): ViewDef {
  return VIEWS[id]
}

/**
 * One palette row per registered view, in `VIEW_KINDS` order. Titles resolve
 * at registration, like the rest of the default table (a locale switch
 * re-registers).
 */
export function viewCommands(
  openView: (id: TabView, arg?: string) => void,
  ctx: ViewContext,
  LL: TranslationFunctions = getLL()
): Command[] {
  return VIEW_KINDS.map((id) => {
    const def = viewDef(id)
    const when = def.when
    return {
      id: def.command.id,
      title: def.command.title(LL),
      group: def.command.group(LL),
      ...(def.command.keys ? { keys: def.command.keys } : {}),
      run: () => openView(id, def.arg?.()),
      ...(when ? { when: () => when(ctx) } : {}),
    }
  })
}
